from localization import tr, term
"""Информация о версии и понятное описание работы с данными."""
import flet as ft
from app_info import APP_TITLE, APP_VERSION


def showDataInfo(page):
    dialog = ft.AlertDialog(title=ft.Text(tr(page, 'Условия использования и данные')),
        content=ft.Column(width=340, height=330, scroll=ft.ScrollMode.AUTO, controls=[
            ft.Text(tr(page, 'Это учебное приложение для ведения проектов по лепке.')),
            ft.Text(tr(page, 'Для аккаунта сохраняются email, хеш пароля, профиль и настройки. Регистрация подтверждается кодом на почту. Для проверки есть отдельный тестовый аккаунт.')),
            ft.Text(tr(page, 'Для сообщества сохраняются публикации, фотографии, комментарии и ответы, лайки, конкурсные заявки и голоса, призовые места и личные уведомления с отметкой прочтения.')),
            ft.Text(tr(page, 'В локальном режиме данные находятся на устройстве. При подключённом API аккаунты, публикации и прогресс мастер-классов находятся на сервере; личные проекты, напоминания о сроках, палитра, встроенный прогресс, личные 3D-модели, избранные уроки и модели, заметки и история поиска — на устройстве.')),
            ft.Text(tr(page, 'Опубликованные фото, описание, выбранные этапы и рецепты видны другим пользователям сообщества. Публикуйте изображения, которыми готовы поделиться.')),
            ft.Text(tr(page, 'Жалобы, решения и журнал модерации хранятся в базе сообщества. Администратор видит аккаунты и жалобы; причины и журнал решений сохраняются после удаления аккаунта для истории модерации.')),
            ft.Text(tr(page, 'Свою публикацию можно удалить. При удалении аккаунта чужие комментарии остаются под заглушкой «Работа удалена пользователем». Ранее скопированные другими людьми рецепты остаются у них.'))]),
        actions=[ft.TextButton(tr(page, 'Понятно'), on_click=lambda event: page.close(dialog))])
    page.open(dialog)


def showAbout(page):
    dialog = ft.AlertDialog(title=ft.Text(tr(page,APP_TITLE)),
        content=ft.Column(width=340, tight=True, scroll=ft.ScrollMode.AUTO, controls=[
            ft.Text(tr(page, 'Версия {v0}', v0=APP_VERSION)),
            ft.Text(tr(page, 'Учебное приложение-помощник для лепки.')),
            ft.Text(tr(page, 'Аккаунт и профиль, смешивание цветов и PNG-рецепты, пошаговые уроки, избранные уроки и личные заметки, проекты с фото и JSON, статистика, калькулятор, таймер, календарь сроков и напоминания внутри приложения, публикации и мастер-классы, конкурсные теги, топ-3 и сетка участников, ответы на комментарии и личные уведомления о событиях, жалобы, их история, панель модерации и пользовательские роли сотрудников, офлайн-галерея 3D, импорт OBJ/MTL, полноэкранный просмотр и схемы этапов.')),
            ft.Text(tr(page, 'Google-вход, push через FCM, AR и перенос пользовательского учебного каталога в личном снимке в этой версии не реализованы. Встроенные 3D-модели и схемы геометрические; это не фотографии и не видео лепки.')),
            ft.Text(tr(page, 'Общее сообщество требует настроенного сервера.'))]),
        actions=[ft.TextButton(tr(page, 'Закрыть'), on_click=lambda event: page.close(dialog))])
    page.open(dialog)
